<template><div><PageHeader title="Notifications" description="System and training-operation activity for your workspace."><template #actions><button class="btn secondary" @click="store.markAllRead">Mark all read</button></template></PageHeader><div class="card"><div class="card-pad"><div class="notice-list"><button v-for="item in store.notifications" :key="item.id" class="notice-item" :class="{unread:item.unread}" style="width:100%;text-align:left" @click="store.markRead(item.id)"><div class="course-icon" :class="item.unread?'':'muted'">🔔</div><div class="notice-copy"><strong>{{item.title}}</strong><p>{{item.description}}</p><small>{{item.time}}</small></div><span v-if="item.unread" class="status-dot" style="background:#2563eb"></span></button></div></div></div></div></template>
<script setup lang="ts">import PageHeader from '../components/PageHeader.vue';import {useAppStore} from '../stores/app';const store=useAppStore()</script>
